       @push('js')            <script>                document.addEventListener('livewire:init', () => {                    const selectizeInstances = {};                    function initializeSelectize({                                                     selector,                                                     livewireEvent,                                                     valueField = 'id',                                                     labelField = 'name',                                                     searchField = 'name',                                                     options = [],                                                     selected = null,                                                     clearOption = false                                                 }) {                        let $select = $(selector);                        if ($select[0]?.selectize) {                            $select[0].selectize.destroy();                        }                        $select.selectize({                            persist: false,                            plugins: ['remove_button', 'clear_button'],                            valueField,                            labelField,                            searchField,                            create: false,                            placeholder: 'Select materials...',                            onChange: function (values) {                                Livewire.dispatch(livewireEvent, [values]);                            },                            onInitialize: function () {                                selectizeInstances[selector] = this;                                if (clearOption) {                                    this.clear();                                    this.clearOptions();                                }                                if (options && options.length) {                                    options.forEach(option => {                                        this.addOption(option);                                    });                                }                                this.refreshOptions(false);                                if (selected && selected.length) {                                    this.setValue(selected);                                }                            }                        });                    }                    initializeSelectize({                        selector: '.selectize_materials',                        livewireEvent: 'materialSelectize',                    });                    initializeSelectize({                        selector: '.selectize_classes',                        livewireEvent: 'classSelectize',                    });                });            </script>@endpush